html:
{%- import "erpnext/templates/print_formats/report_print_macros.html" as rp -%}
{%- set show_company = no_letterhead if no_letterhead is defined else not letter_head -%}
{%- set payable = report.report_name == "Accounts Payable" -%}
{%- set sign = -1 if payable else 1 -%}
{%- set rows = [] -%}
{%- for row in data if row is mapping and row.voucher_no and not row.is_total_row and row.outstanding -%}
	{%- set ignore = rows.append(row) -%}
{%- endfor -%}
{%- set parties = rows | map(attribute="party") | unique | list -%}
{%- set party_type = filters.party_type or (rows[0].party_type if rows else ("Supplier" if payable else "Customer")) -%}
{%- set as_on = rp.date(filters.report_date) -%}
{%- set company_name = frappe.db.get_value("Company", filters.company, "company_name") or filters.company -%}
{%- set party_docs = {} -%}
{%- for doc in (frappe.get_all(party_type, filters={"name": ["in", parties]}, fields=["*"]) if parties else []) -%}
	{%- set ignore = party_docs.update({doc.name: doc}) -%}
{%- endfor -%}
{%- set currencies = rows | map(attribute="currency") | select | unique | list -%}
{%- set symbols = {} -%}
{%- for cur in (frappe.get_all("Currency", filters={"name": ["in", currencies]}, fields=["name", "symbol"]) if currencies else []) -%}
	{%- set ignore = symbols.update({cur.name: cur.symbol}) -%}
{%- endfor -%}
{%- set company_block = rp.company_header(filters.company) if show_company else "" -%}
{{ rp.styles("portrait") }}
<div class="rpf">
	{%- for party in parties %}
	{%- set party_rows = rows | selectattr("party", "equalto", party) | list %}
	{%- set balance = party_rows | map(attribute="outstanding") | map("float") | sum %}
	{%- set currency = party_rows[0].currency %}
	{%- set doc = party_docs.get(party) or {} %}
	<div class="rpf-page">
		{{ company_block }}
		<table class="rpf-layout">
			<tr>
				<td class="muted">{{ _("Ref") }}: {{ _("Balance Confirmation") }} / {{ party | e }}</td>
				<td class="align-right">{{ rp.date(frappe.utils.today()) }}</td>
			</tr>
		</table>
		<div class="rpf-address">
			{{ _("To") }},<br>
			<b>{{ (party_rows[0].supplier_name or party_rows[0].customer_name or party) | e }}</b><br>
			{%- if doc.primary_address %}{{ doc.primary_address | replace("<br>", ", ") | striptags | trim(", ") | e }}<br>{% endif %}
			{%- if doc.gstin or doc.tax_id %}{{ _("GSTIN") }} {{ (doc.gstin or doc.tax_id) | e }}{% endif %}
		</div>
		<p class="rpf-subject-line"><b>{{ _("Subject: Confirmation of balance as on {0}").format(as_on) }}</b></p>
		<p>{{ _("Dear Sir/Madam,") }}</p>
		<p>
			{{ _("As per our books of account, the balance in your account as on {0} is {1} {2} ({3}).").format(
				"<b>" ~ as_on ~ "</b>",
				"<b>" ~ frappe.utils.fmt_money(balance | abs, currency=currency),
				(_("Dr") if sign * balance > 0 else _("Cr")) ~ "</b>",
				frappe.utils.money_in_words(balance | abs, currency)
			) }}
			{%- if (balance > 0) == payable %} {{ _("This amount is payable by us to you.") }}
			{%- else %} {{ _("This amount is receivable by us from you.") }}{% endif %}
		</p>
		<p>{{ _("Please confirm this balance by {0}. If it does not agree with your books, please send us your statement of account for the period so that we can reconcile the difference.").format(rp.date(frappe.utils.add_days(frappe.utils.today(), 15))) }}</p>
		<p>{{ _("The list of pending bills is given below.") }}</p>
		<table class="rpf-layout rpf-sign">
			<tr>
				<td class="half">
					<div class="rpf-box rpf-reply">
						<div class="rpf-label">{{ _("Your confirmation") }}</div>
						<div class="rpf-reply-options">
							&#9744; {{ _("We confirm the above balance.") }}<br>
							&#9744; {{ _("Our books show {0} ________________ Dr / Cr.").format(symbols.get(currency) or currency) }}
						</div>
						<div class="rpf-label rpf-sign-line">{{ _("Signature, name and stamp") }}</div>
					</div>
				</td>
				<td class="half align-right">
					<div>{{ _("For {0}").format(company_name | e) }}</div>
					<div class="rpf-label rpf-signatory">{{ _("Authorised Signatory") }}</div>
				</td>
			</tr>
		</table>
		<div class="rpf-title rpf-section-title">{{ _("Pending bills as on {0}").format(as_on) }}</div>
		<table class="rpf-grid">
			<colgroup><col style="width: 80px"><col><col style="width: 80px"><col style="width: 128px"></colgroup>
			<thead>
				<tr>
					<th>{{ _("Date") }}</th>
					<th>{{ _("Reference No.") }}</th>
					<th>{{ _("Due On") }}</th>
					<th class="num">{{ _("Pending Amount") }}</th>
				</tr>
			</thead>
			<tbody>
				{%- for row in party_rows %}
				<tr>
					<td class="nowrap">{{ rp.date(row.posting_date) }}</td>
					<td>{{ (row.bill_no or row.voucher_no) | e }}</td>
					<td class="nowrap">{{ rp.date(row.due_date) }}</td>
					<td class="num">{{ rp.drcr(sign * row.outstanding) }}</td>
				</tr>
				{%- endfor %}
				<tr class="total">
					<td></td>
					<td>{{ _("Total") }}</td>
					<td></td>
					<td class="num"><span class="double">{{ rp.drcr(sign * balance) }}</span></td>
				</tr>
			</tbody>
		</table>
		{{ rp.footnote() }}
	</div>
	{%- else %}
	<div class="rpf-empty">{{ _("No pending balance to confirm") }}</div>
	{%- endfor %}
</div>
